def host(a,b):
    G=nx.complete_bipartite_graph(a,b)
    for j in range(a//3):G.add_edges_from([(3*j,3*j+1),(3*j+1,3*j+2)])
    if a%3==2:G.add_edge(a-2,a-1)
    return G

def brute(G):
    total=0
    for s in G:
        def dfs(v,seen):
            ans=int(len(seen)>=3 and G.has_edge(v,s))
            for w in G[v]:
                if w>s and w not in seen:ans+=dfs(w,seen|{w})
            return ans
        total+=dfs(s,{s})
    assert total%2==0
